/* Shape support */

func _get_shape_size(tls *libc.TLS, hash_size Tsize_t, prop_size Tsize_t) (r Tsize_t) {
	return hash_size*uint32(4) + uint32(48) + prop_size*uint32(8)
}

func _get_shape_from_alloc(tls *libc.TLS, sh_alloc uintptr, hash_size Tsize_t) (r uintptr) {
	return sh_alloc + uintptr(hash_size)*4
}

func _prop_hash_end(tls *libc.TLS, sh uintptr) (r uintptr) {
	return sh
}

func _get_alloc_from_shape(tls *libc.TLS, sh uintptr) (r uintptr) {
	return _prop_hash_end(tls, sh) - uintptr(libc.Int32FromUint32((*TJSShape)(unsafe.Pointer(sh)).Fprop_hash_mask)+libc.Int32FromInt32(1))*4
}

func _get_shape_prop(tls *libc.TLS, sh uintptr) (r uintptr) {
	return sh + 48
}

func _init_shape_hash(tls *libc.TLS, rt uintptr) (r int32) {
	(*TJSRuntime)(unsafe.Pointer(rt)).Fshape_hash_bits = int32(4) /* 16 shapes */
	(*TJSRuntime)(unsafe.Pointer(rt)).Fshape_hash_size = int32(1) << (*TJSRuntime)(unsafe.Pointer(rt)).Fshape_hash_bits
	(*TJSRuntime)(unsafe.Pointer(rt)).Fshape_hash_count = 0
	(*TJSRuntime)(unsafe.Pointer(rt)).Fshape_hash = Xjs_mallocz_rt(tls, rt, uint32(4)*libc.Uint32FromInt32((*TJSRuntime)(unsafe.Pointer(rt)).Fshape_hash_size))
	if !((*TJSRuntime)(unsafe.Pointer(rt)).Fshape_hash != 0) {
		return -int32(1)
	}
	return 0
}

// C documentation
//
//	/* same magic hash multiplier as the Linux kernel */
func _shape_hash(tls *libc.TLS, h Tuint32_t, val Tuint32_t) (r Tuint32_t) {
	return (h + val) * uint32(0x9e370001)
}

// C documentation
//
