	v9 = uint32((*Tpacked_u16)(unsafe.Pointer((*TJSFunctionDef)(unsafe.Pointer(fd)).Fbyte_code.Fbuf + uintptr((*TJSFunctionDef)(unsafe.Pointer(fd)).Flast_opcode_pos) + uintptr(5))).Fv)
	goto _18
_18:
